# ------------------------------------------------------------------ service page builder
def service(slug, title, desc, h1, intro, image, crumb, details, cards, why_cards, benefit_cfg, faq_items, approach_cfg=None, og=None, extra=None):
    secs = [('ihero', {'eyebrow': 'Treatment', 'h1': h1, 'text': intro, 'image': image, 'image_alt': h1, 'crumb': crumb, 'ratio': '1120/600'}),
            ('detail_cards', {'title': 'Treatment details', 'text': 'As published for the main treatment in this family. Your doctor confirms the plan after assessment.', 'items': details}),
            ('services', {'eyebrow': 'What we use', 'title': cards['title'], 'text': cards['text'], 'cards': cards['cards'], 'id': 'options'}),
            ('why', {'eyebrow': 'Why Da Vinci', 'title': why_cards['title'], 'text': '', 'img': why_cards.get('img', 'assets/img/why-doctor.webp'), 'img_alt': 'Da Vinci Clinic doctor', 'cards': why_cards['cards']}),
            ('benefit', benefit_cfg),
            ('work', WORK)]
    if approach_cfg: secs.append(('approach', approach_cfg))
    if extra: secs += extra
    secs += [('faq', {'title': 'Frequently asked questions', 'text': 'Answers from the Da Vinci doctors.', 'items': faq_items}), ('posts', BLOG_SECTION), ('cta', CTA)]
    return {'slug': slug, 'title': title, 'desc': desc, 'sections': secs, 'faq': {'items': faq_items}, 'og': og or image,
            'breadcrumb': [('Home', '/'), ('Treatments', '/treatments/'), (crumb, '/' + slug + '/')]}

def card(title, text, img, href='treatments/'): return {'title': title, 'text': text, 'img': img, 'alt': title, 'href': href}

