            {'title': 'Step 2: Skin tightening', 'text': 'BTL Exion, Oligio, Oligio X or Fotona 4D/5D/6D laser lift to contract and rebuild collagen in the dermis.', 'pills': ['Oligio X', 'BTL Exion', 'Fotona laser lift'], 'img': 'assets/img/svc-facelift.webp', 'alt': 'Skin tightening step'},
