        rows.append(('split', {'rev': i % 2 == 1, 'title': d['name'], 'img': d['img'], 'img_alt': d['alt'], 'paras': [d['role'] + ' · ' + d['branch'], d['bio'], 'Credentials: ' + '; '.join(d['creds']) + '.', '“' + d['quote'] + '”']}))
