def branch_page(b, h1, intro, doctors_here, gallery_items, extra_faq, img):
    d = [x for x in DOCTORS if x['name'] in doctors_here]
    rating = f'<p>{b["rating"]}★ on Google from {b["reviews"]} reviews for this branch.</p>' if b['rating'] else '<p>Reviews for this branch are on Google.</p>'
    return {'slug': b['id'], 'title': f'Aesthetic Clinic in {b["short"]} KL | {b["name"]}', 'desc': f'{b["name"]}: doctor-led aesthetic clinic at {b["address"]}. Facelift, pico laser, skin boosters, fillers and body contouring by LCP-certified doctors. Open daily.', 'og': img,
        'breadcrumb': [('Home', '/'), (b['short'], '/' + b['id'] + '/')], 'faq': {'items': extra_faq}, 'sections': [
            ('ihero', {'eyebrow': 'Our clinics', 'h1': h1, 'text': intro, 'image': img, 'image_alt': b['name'], 'crumb': b['short'], 'ratio': '1120/600'}),
            ('info_grid', {'eyebrow': 'Visit', 'title': f'Visit {b["name"]}', 'text': '', 'items': [
                {'title': 'Address', 'html': f'<p>{b["address"]}</p><p><a href="{b["map"]}" target="_blank" rel="noopener">Open in Google Maps</a></p>'},
                {'title': 'Opening hours', 'html': '<p>Monday to Friday 10:00am to 7:00pm</p><p>Saturday and Sunday 10:00am to 5:30pm</p>'},
                {'title': 'Call or WhatsApp', 'html': f'<p>Landline <a href="tel:{b["tel"].replace(" ","")}">{b["tel"]}</a></p><p>WhatsApp <a href="{b["wa"]}" target="_blank" rel="noopener">{b["wa_num"]}</a></p>'},
                {'title': 'Doctors at this branch', 'html': '<p>' + ', '.join(doctors_here) + '</p>' + rating}]}),
            ('gallery', {'eyebrow': 'Take a look inside', 'title': 'Clinic environment', 'text': 'A calm, private space designed around the consultation.', 'items': gallery_items}),
            ('map_block', {'src': 'https://www.google.com/maps?q=' + b['address'].replace(' ', '+') + '&output=embed', 'title': b['name'] + ' map'}),
            ('team', dict(TEAM_SECTION, title=f'Doctors at {b["short"]}', text='Tap a doctor to read their credentials.', members=d or DOCTORS)),
            ('testimonials', TESTIMONIALS),
            ('faq', {'title': f'Questions about the {b["short"]} clinic', 'text': '', 'items': extra_faq}),
            ('cta', dict(CTA, title=f'Book at {b["short"]}', text=f'WhatsApp {b["wa_num"]} or use the form. Open seven days a week.'))]}

